const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const bellingham = ee.Geometry.Point([-122.4787, 48.7519]); // Bellingham, Washington
  const startDate = '2021-09-01';
  const endDate = '2021-11-30';
  const scale = 5000; // CHIRPS resolution is about 5.5 km (0.05 degrees)

  // 2. Data Acquisition
  let chirpsCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(bellingham);

  const collectionSize = await chirpsCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No CHIRPS images found for Bellingham between September and November 2021.");
    console.log("C1");
    return;
  }

  // Calculate total precipitation
  // Sum all daily precipitation images into a single image
  const totalPrecipitationImage = chirpsCollection.select('precipitation').sum();

  // 3. Processing & Calculation
  const stats = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.sum().unweighted().setOutputs(['sum']), // Use sum to get total, unweighted for precipitation sum
    geometry: bellingham,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  let totalPrecipitationMm = stats && stats.sum; // precipitation is in mm

  if (totalPrecipitationMm === null || totalPrecipitationMm === undefined) {
    console.log("Calculation for total precipitation failed.");
    console.log("C3");
    return;
  }

  // Convert total precipitation from mm to cm
  const totalPrecipitationCm = totalPrecipitationMm / 10;

  // Validate for C2 (No Valid Pixels) - although less likely with sum and point geometry
  // We can get a pixel count if we use reduceRegion with count, but for sum, if value is not null,
  // it implies there were valid pixels in the region.
  // Let's get a basic pixel count for the first image in the collection to ensure coverage.
  const firstImage = chirpsCollection.first();
  const pixelCount = await firstImage.select('precipitation').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bellingham,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const validPixels = pixelCount && pixelCount.precipitation;

  if (validPixels === 0) {
    console.log("Images exist, but no valid pixels found after reduction (C2).");
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer
  const thresholdCm = 30; // 30 cm

  console.log(`Bellingham Rainfall (Sep-Nov 2021): ${totalPrecipitationMm.toFixed(2)} mm`);
  console.log(`Bellingham Rainfall (Sep-Nov 2021): ${totalPrecipitationCm.toFixed(2)} cm`);
  console.log(`Images processed: ${collectionSize}, Valid pixels (first img): ${validPixels}`);

  if (totalPrecipitationCm >= thresholdCm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
